const char str_002762e4[] = "!!ARBfp1.0\nOPTION ARB_precision_hint_fastest;\nOUTPUT oC0AfterFog = result.color;\nTEMP r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15, oC0;\nPARAM c23 = program.env[23];\nATTRIB t0 = fragment.texcoord[ 0 ];\nTEX   r0, t0, texture[ 0 ], 2D;\nMUL r1.w, r0.w, c23.w;\nMAD r0.x, r0.x, c23.x, r1.w;\nMAD r0.y, r0.y, c23.y, r1.w;\nMAD r0.z, r0.z, c23.z, r1.w;\nMOV oC0, r0;\nMAX r15.x, fragment.fogcoord.x, 0;MIN  r15.x, r15.x, 1;LRP oC0AfterFog.xyz, r15.x, oC0, state.fog.color;MOV oC0AfterFog.w, oC0.w;END"; /* str_002762e4 */
