const char str_00276500[] = "!!ARBfp1.0\nOPTION ARB_precision_hint_fastest;\nOUTPUT oC0AfterFog = result.color;\nTEMP r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15, oC0;\nPARAM c23 = program.env[23];\nPARAM c0 = { 0.5, 1.00100005, 1, 0 };\nATTRIB t0 = fragment.texcoord[ 0 ];\nATTRIB t1 = fragment.texcoord[ 1 ];\nATTRIB t2 = fragment.texcoord[ 2 ];\nATTRIB t3 = fragment.texcoord[ 3 ];\nTEX      r0, t0, texture[ 0 ], 2D;\nMOV r1.xyz, t1;\nMAD r2.xyz, r0.w, r1, t3;\nMAD    r0.xyz, r0.y, t2, r2;\nDP3    r2.x, r0, r0;\nRSQ    r0.w, r2.x;\nMUL r0.w, r0.w, c0.y;\nMUL    r0.xyz, r0, r0.w;\nMUL    r2.xyz, t2, c0.x;\nMUL r3.xyz, r2, c23.y;\nMUL    r2.xyz, t1, c0.x;\nMAD    r2.xyz, r2, c23.x, r3;\nMAD r1.xyz, r1, c0.x, t3;\nMAD    r1.xyz, t2, c0.x, r1;\nMAD    r1.xyz, r1, c23.z, r2;\nMAD    r0.xyz, r0, c23.w, r1;\nADD    r0.xyz, r0, c0.z;\nMUL    r0.xyz, r0, c0.x;\nMOV r0.w, c0.z;\nMOV oC0, r0;\nMAX r15.x, fragment.fogcoord.x, 0;MIN  r15.x, r15.x, 1;LRP oC0AfterFog.xyz, r15.x, oC0, state.fog.color;MOV oC0AfterFog.w, oC0.w;END"; /* str_00276500 */
