const char str_00269ec3[] = "r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;\\nADDRESS a0;\\nMOV oFog.x, 1;\\nPARAM c16 = program.env[16];\\nPARAM c23[4] =  { program.env[23..26] };\\nPARAM c4[3] =  { program.env[4..6] };\\nPARAM c0 = { 0, 0, 0, 0 };\\nATTRIB v0 = vertex.attrib[0];\\nATTRIB v1 = vertex.attrib[5];\\nATTRIB v2 = vertex.attrib[8];\\nATTRIB v3 = vertex.attrib[9];\\nATTRIB v4 = vertex.attrib[10];\\nATTRIB v5 = vertex.attrib[3];\\nDP4 oPos.x, v0, c23[0];\\nDP4 oPos.y, v0, c23[1];\\nDP4 oPos.z, v0, c23[2];\\nDP4 r0.x, v0, c4[0];\\nDP4 r0.y, v0, c4[1];\\nDP4 r0.z, v0, c4[2];\\nADD r0.xyz, -r0, c16;\\nRCP r0.w, c16.w;\\nDP4 oPos.w, v0, c23[3];\\nMUL oT4.xyz, r0, r0.w;\\nDP3 r0.x, v5, c4[0];\\nDP3 r0.y, v5, c4[1];\\nDP3 r3.x, v3, c4[0];\\nDP3 r3.y, v3, c4[1];\\nDP3 r3.z, v3, c4[2];\\nDP3 r2.x, v4, c4[0];\\nDP3 r2.y, v4, c4[1];\\nDP3 r2.z, v4, c4[2];\\nDP3 r0.z, v5, c4[2];\\nADD r1.xyz, r3, r2;\\nADD oT1.xyz, r3, r3;\\nADD oT2.xyz, r2, r2;\\nADD oT3.xyz, r0, -r1;\\nMOV oD0, v1;\\nMOV oT0.xy, v2;\\nMOV oT5.xyz, c0.x;\\nEND"; /* str_00269ec3 */
